insert into public.site_settings (id, data)
values (1, '{"name":"Rashi Chugh","role":"Graphic Designer · Motion Artist · Video Editor","heroTitle":"Making ideas","heroAccent":"look alive.","intro":"I’m Rashi — a graphic designer and motion artist turning briefs into bold, colourful, feels-something design.","location":"Gurugram, India","availability":"Available for freelance & project-based work","email":"rashichugh610@gmail.com","phone":"+91 97283 26661","linkedinUrl":"https://www.linkedin.com/in/rashi-chugh-298430423/","behanceUrl":"https://www.behance.net/rashichugh","resumeUrl":"/resume/rashi-chugh-resume.pdf","profileImage":"/images/profile/rashi-portrait.webp","aboutTitle":"Curious by nature. Colourful by choice.","aboutBody":"I’m a Gurugram-based graphic designer, video editor and motion graphics artist, currently pursuing a B.Voc at Jagannath University & Arena Animation. I love expressive type, playful colour and visuals that make people pause. From client logos to game assets and motion experiments, I enjoy turning loose ideas into thoughtful, memorable design.","services":[{"title":"Graphic Design","description":"Posters, layouts and visual experiments with type, texture and a point of view.","color":"#DDF48B","icon":"PenTool"},{"title":"Brand Identity","description":"Distinctive logos and identity systems that give brands a personality of their own.","color":"#F4B8D0","icon":"Shapes"},{"title":"Motion & Video","description":"Motion graphics and edits that bring rhythm, energy and storytelling to the frame.","color":"#A9C6FF","icon":"Clapperboard"},{"title":"Social Content","description":"Scroll-stopping campaign creatives, promotional posts and content built to connect.","color":"#FF936F","icon":"Megaphone"}],"tools":[{"name":"Photoshop","icon":"/icons/tools/photoshop.svg","color":"#F5F0E6","shape":"arch"},{"name":"Illustrator","icon":"/icons/tools/illustrator.svg","color":"#DDF48B","shape":"square"},{"name":"Premiere Pro","icon":"/icons/tools/premiere-pro.svg","color":"#AFC8FF","shape":"circle"},{"name":"After Effects","icon":"/icons/tools/after-effects.svg","color":"#F5F0E6","shape":"blob"},{"name":"Audition","icon":"/icons/tools/audition.svg","color":"#DDF48B","shape":"leaf"},{"name":"Canva","icon":"/icons/tools/canva.svg","color":"#AFC8FF","shape":"arch"},{"name":"AI Design Tools","icon":"/icons/tools/ai-design-tools.svg","color":"#FFCF54","shape":"square"}],"experience":[{"role":"Graphic Design Intern","company":"Spectre Rex · Frykar cooking game","period":"JUL 2026 — NOW","description":"Designing the game logo and visual assets in Photoshop and Illustrator, with a focus on style consistency, detail and collaborative feedback.","color":"#DDF48B"},{"role":"Graphic Designer & Video Editor","company":"Freelance","period":"2025 — NOW","description":"Creating custom logos, editorial layouts and social visuals for clients, plus gaming video edits in After Effects. From first brief to final refinement.","color":"#F4B8D0"}],"education":[{"degree":"B.Voc","institution":"Jagannath University & Arena Animation","period":"2025 — Present","description":"","color":"#AFC8FF"}]}'::jsonb)
