values
  ('motion-graphics', 'Motion Graphics', 'Motion & Video', '2026', 'A collection of motion studies and edits — mixing type, rhythm and visual storytelling.', '/images/projects/motion-00.webp', '#FFC94A', array['Motion Graphics', 'Video Editing']::text[], array['After Effects', 'Premiere Pro']::text[], 'https://www.behance.net/gallery/254091283/Motion-Graphics', true, 'published', 0, '[{"id":"motion-heading","type":"heading","data":{"text":"Design, set in motion.","level":2}},{"id":"motion-copy","type":"paragraph","data":{"html":"A set of motion graphics and video editing explorations created with After Effects and Premiere Pro. Each piece plays with pacing, transitions and sound to make the visual feel alive."}},{"id":"motion-video-1","type":"video","data":{"url":"/videos/motion-01.mp4","caption":"Motion study · 01","poster":"/images/projects/motion-01-poster.webp"}},{"id":"motion-video-2","type":"video","data":{"url":"/videos/motion-02.mp4","caption":"Motion study · 02","poster":"/images/projects/motion-02-poster.webp"}},{"id":"motion-video-3","type":"video","data":{"url":"/videos/motion-03.mp4","caption":"Motion study · 03","poster":"/images/projects/motion-03-poster.webp"}}]'::jsonb),
  ('logo-design', 'Logo Design', 'Brand Identity', '2026', 'Wordmarks, symbols and playful identities designed to make a lasting first impression.', '/images/projects/logo-00.webp', '#F4B8D0', array['Logo Design', 'Visual Identity']::text[], array['Illustrator', 'Photoshop']::text[], 'https://www.behance.net/gallery/250965151/Logo-Design', true, 'published', 1, '[{"id":"logo-heading","type":"heading","data":{"text":"Marks with meaning.","level":2}},{"id":"logo-copy","type":"paragraph","data":{"html":"A collection of logo explorations spanning wordmarks, symbolic identities and playful brand directions. The focus: simple forms, memorable silhouettes and type that feels at home with each brand."}},{"id":"logo-gallery","type":"gallery","data":{"images":["/images/projects/logo-02.webp","/images/projects/logo-03.webp","/images/projects/logo-04.webp","/images/projects/logo-05.webp"],"captions":["Brew Clip · Wordmark","Svarun · Brand identity","Himalayan Sip · Identity","Waffle Story · Logo"],"layout":"grid"}},{"id":"logo-note","type":"callout","data":{"text":"Made with Adobe Illustrator & Photoshop.","tone":"lime"}}]'::jsonb),
  ('posters', 'Posters', 'Graphic Design', '2026', 'Type, texture and composition come together in a series of expressive poster studies.', '/images/projects/posters-00.webp', '#DDF48B', array['Poster Design', 'Typography', 'Layout']::text[], array['Photoshop']::text[], 'https://www.behance.net/gallery/250965307/Posters', true, 'published', 2, '[{"id":"poster-heading","type":"heading","data":{"text":"Type. Texture. Impact.","level":2}},{"id":"poster-copy","type":"paragraph","data":{"html":"A series of poster studies across product, automotive and cultural themes. Each composition explores a different visual mood — from clean product storytelling to layered, high-energy graphics."}},{"id":"poster-gallery","type":"gallery","data":{"images":["/images/projects/posters-02.webp","/images/projects/posters-03.webp","/images/projects/posters-04.webp","/images/projects/posters-05.webp","/images/projects/posters-06.webp","/images/projects/posters-07.webp","/images/projects/posters-08.webp"],"captions":["Comet · Product poster","Mahabhakti · Cultural poster","Kawasaki · Automotive","Nike SB Dunk · Product","Poster study","Aviation · Poster","Poster exploration"],"layout":"masonry"}}]'::jsonb),
  ('illustrations', 'Illustrations', 'Illustration', '2026', 'Character-led illustrations and digital drawing experiments with a playful streak.', '/images/projects/illustrations-00.webp', '#A9C6FF', array['Illustration', 'Digital Art', 'Character']::text[], array['Photoshop', 'Illustrator']::text[], 'https://www.behance.net/gallery/250965035/Illustrations', true, 'published', 3, '[{"id":"illustration-heading","type":"heading","data":{"text":"Drawing outside the lines.","level":2}},{"id":"illustration-copy","type":"paragraph","data":{"html":"A mix of character studies, vector illustration and digital painting. These personal explorations are a space to experiment with expression, colour and different levels of detail."}},{"id":"illustration-gallery","type":"gallery","data":{"images":["/images/projects/illustrations-02.webp","/images/projects/illustrations-03.webp","/images/projects/illustrations-04.webp","/images/projects/illustrations-05.webp","/images/projects/illustrations-06.webp"],"captions":["Character study","Lion · Vector illustration","Luffy · Digital illustration","The Mandalorian · Digital painting","Character exploration"],"layout":"masonry"}}]'::jsonb),
  ('creative-posts', 'Creative Posts', 'Social Media', '2026', 'Promotional creatives and social posts built to stop the scroll and start a feeling.', '/images/projects/creative-posts-00.webp', '#FF936F', array['Social Media', 'Campaign Design', 'Content']::text[], array['Photoshop']::text[], 'https://www.behance.net/gallery/250964801/Creative-Posts', true, 'published', 4, '[{"id":"creative-heading","type":"heading","data":{"text":"Made for the pause.","level":2}},{"id":"creative-copy","type":"paragraph","data":{"html":"A selection of social media creatives across food, automotive and festive communication. Bold hierarchy, clear messaging and a distinct mood keep each post recognisably its own."}},{"id":"creative-gallery","type":"gallery","data":{"images":["/images/projects/creative-posts-02.webp","/images/projects/creative-posts-03.webp","/images/projects/creative-posts-04.webp","/images/projects/creative-posts-05.webp"],"captions":["GT Mustang · Automotive creative","Grand Opening · Restaurant creative","Janmashtami · Festive creative","Food Menu · Promotional creative"],"layout":"grid"}}]'::jsonb)
